<script setup>import{computed,ref}from'vue';const enabled=ref(true),cycle=ref(0);const rows=computed(()=>enabled.value?[['LOAD','A','B','C','D'],['COMPUTE','·','A','B','C'],['STORE','·','·','A','B']]:[['LOAD','A','·','B','·'],['COMPUTE','·','A','·','B'],['STORE','·','·','A','·']])</script>
<template><section class="db arch-overlay"><header><b>DOUBLE BUFFER TIMELINE</b><span>steady state = max(Tload, Tcompute)</span></header><div class="grid"><template v-for="row in rows" :key="row[0]"><strong>{{row[0]}}</strong><i v-for="(v,j) in row.slice(1)" :key="j" :class="[row[0].toLowerCase(),{active:j===cycle}]">{{v}}</i></template></div><footer><button @click="enabled=!enabled">{{enabled?'Disable':'Enable'}} overlap</button><button @click="cycle=(cycle+1)%4">Step</button><button @click="cycle=0">Reset</button><b>{{enabled?'2 buffers · overlapped':'1 buffer · serialized'}}</b></footer></section></template>
